require_once dirname(__DIR__) . '/_common.php';$id=isset($_GET['id'])?(int)$_GET['id']:0;$stmt=$pdo->prepare('SELECT a.*,u.username,u.email AS login_email FROM anggota a LEFT JOIN users u ON u.id=a.user_id WHERE a.id=?');$stmt->execute([$id]);$item=$stmt->fetch();if(!$item){osis_set_flash('error','Data anggota tidak ditemukan.');osis_redirect('admin/anggota/index.php');}$pageTitle='Edit anggota';$error='';
if(osis_admin_is_post()){osis_verify_csrf();$nama=osis_post_string('nama',120);$nis=osis_post_string('nis',40);$kelas=osis_post_string('kelas',60);$hp=osis_post_string('no_hp',30);$email=osis_post_string('email',120);$alamat=osis_post_string('alamat',2000);$username=osis_post_string('username',50);$password=isset($_POST['password'])?(string)$_POST['password']:'';$status=isset($_POST['status'])&&$_POST['status']==='alumni'?'alumni':'aktif';
if($nama===''||$username===''){$error='Nama dan username wajib diisi.';}elseif($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL)){$error='Format email tidak valid.';}elseif($password!==''&&strlen($password)<8){$error='Kata sandi baru minimal 8 karakter.';}elseif(!$item['user_id']&&strlen($password)<8){$error='Anggota ini belum memiliki akun. Masukkan kata sandi awal minimal 8 karakter.';}else{try{$foto=osis_store_uploaded_image(isset($_FILES['foto'])?$_FILES['foto']:null,'anggota');$pdo->beginTransaction();if($item['user_id']){$sql='UPDATE users SET nama=?,username=?,email=?';$params=[$nama,$username,$email?:null];if($password!==''){$sql.=',password_hash=?';$params[]=password_hash($password,PASSWORD_DEFAULT);}$sql.=' WHERE id=?';$params[]=$item['user_id'];$pdo->prepare($sql)->execute($params);}else{$newPassword=$password!==''?$password:bin2hex(random_bytes(6));$stmt=$pdo->prepare("INSERT INTO users(nama,username,email,password_hash,role,aktif) VALUES(?,?,?,?,'anggota',1)");$stmt->execute([$nama,$username,$email?:null,password_hash($newPassword,PASSWORD_DEFAULT)]);$item['user_id']=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE anggota SET user_id=? WHERE id=?')->execute([$item['user_id'],$id]);}
$sql='UPDATE anggota SET nama=?,nis=?,kelas=?,no_hp=?,email=?,alamat=?,status=?';$params=[$nama,$nis?:null,$kelas?:null,$hp?:null,$email?:null,$alamat?:null,$status];if($foto){$sql.=',foto=?';$params[]=$foto;}$sql.=' WHERE id=?';$params[]=$id;$pdo->prepare($sql)->execute($params);$pdo->commit();if($foto)osis_delete_uploaded_file($item['foto']);osis_log_activity('Memperbarui data anggota: '.$nama);osis_set_flash('success','Data anggota berhasil diperbarui.');osis_redirect('admin/anggota/index.php');}catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();$error=osis_admin_handle_error($exception);}}}
osis_admin_page_start($pageTitle);
?>
<div class="admin-form-wrap"><a class="back-link" href="<?=osis_e(osis_url('admin/anggota/index.php'))?>">← Daftar anggota</a><div class="admin-panel form-panel"><span class="eyebrow">PERBARUI DATA & AKUN</span><h2>Edit anggota</h2><?php if($error):?><div class="alert alert-error"><?=osis_e($error)?></div><?php endif;?><form method="post" enctype="multipart/form-data" data-validate-form><?=osis_csrf_input()?><div class="form-grid"><div><label for="nama">Nama lengkap</label><input id="nama" name="nama" required maxlength="120" value="<?=osis_e(isset($_POST['nama'])?$_POST['nama']:$item['nama'])?>"></div><div><label for="nis">NIS</label><input id="nis" name="nis" maxlength="40" value="<?=osis_e(isset($_POST['nis'])?$_POST['nis']:$item['nis'])?>"></div><div><label for="kelas">Kelas</label><input id="kelas" name="kelas" maxlength="60" value="<?=osis_e(isset($_POST['kelas'])?$_POST['kelas']:$item['kelas'])?>"></div><div><label for="no_hp">Nomor kontak</label><input id="no_hp" name="no_hp" maxlength="30" value="<?=osis_e(isset($_POST['no_hp'])?$_POST['no_hp']:$item['no_hp'])?>"></div><div><label for="email">Email</label><input id="email" name="email" type="email" maxlength="120" value="<?=osis_e(isset($_POST['email'])?$_POST['email']:$item['email'])?>"></div><div><label for="status">Status</label><select id="status" name="status"><option value="aktif" <?=isset($_POST['status'])?($_POST['status']==='aktif'?'selected':''):($item['status']==='aktif'?'selected':'')?>>Aktif</option><option value="alumni" <?=isset($_POST['status'])?($_POST['status']==='alumni'?'selected':''):($item['status']==='alumni'?'selected':'')?>>Alumni</option></select></div></div><label for="alamat">Alamat</label><textarea id="alamat" name="alamat" rows="3"><?=osis_e(isset($_POST['alamat'])?$_POST['alamat']:$item['alamat'])?></textarea><div class="form-divider"><span>AKUN UNTUK MASUK</span></div><div class="form-grid"><div><label for="username">Username</label><input id="username" name="username" required maxlength="50" value="<?=osis_e(isset($_POST['username'])?$_POST['username']:$item['username'])?>"></div><div><label for="password">Kata sandi baru <span class="optional">(kosongkan jika tidak diubah)</span></label><input id="password" name="password" type="password" minlength="8" autocomplete="new-password"></div></div><?php if($item['foto']):?><div class="current-upload"><img src="<?=osis_e(osis_image_url($item['foto']))?>" alt="Foto saat ini"><span>Foto saat ini</span></div><?php endif;?><label for="foto">Ganti foto <span class="optional">JPG, PNG, WEBP · maks. 5 MB</span></label><input id="foto" name="foto" type="file" accept="image/jpeg,image/png,image/webp"><div class="form-actions"><a class="button button-outline" href="<?=osis_e(osis_url('admin/anggota/index.php'))?>">Batal</a><button class="button button-primary" type="submit">Simpan perubahan <span>↗</span></button></div></form></div></div>
